import {makeDigitalGift} from './digital-export.js';
import {downloadFile} from './experience.js';
import {mediaSize} from './media-compression.js';
export function initCloudDelivery({billing,getData,getAudio,getState,onRestore,toast}){
 const panel=document.createElement('section');panel.className='cloud-delivery';panel.innerHTML='<h3>Um link para o seu mimo.</h3><p>Publique o presente com as fotos e o áudio. Quem recebe abre pelo link, sem precisar de uma conta. Você também pode guardar a cópia para compartilhar como arquivo.</p><p class="cloud-environment"></p><button type="button" class="button primary cloud-publish">Publicar e criar meu link</button><p class="cloud-status" role="status"></p><div class="cloud-result" hidden><label>Link do presente<input class="cloud-link" readonly></label><div class="cloud-actions"><button type="button" class="cloud-copy">Copiar link</button><a class="cloud-open" target="_blank" rel="noopener noreferrer">Abrir como quem recebe</a></div><canvas class="cloud-qr" width="220" height="220" role="img" aria-label="QR Code do presente publicado"></canvas><button type="button" class="cloud-qr-save">Baixar QR Code</button><p class="cloud-expiry"></p></div><details class="cloud-access"><summary>Guardar acesso ou voltar em outro aparelho</summary><p>O arquivo de acesso permite editar e atualizar a compra. Guarde só para você. Para presentear alguém, envie o link do mimo ou o arquivo do presente.</p><button type="button" class="cloud-save-access">Guardar meu acesso</button><label>Recuperar uma compra<input class="cloud-restore-access" type="file" accept="application/json,.json"></label><label class="cloud-purchase-label" hidden>Compra<select class="cloud-purchase-select"></select></label><button type="button" class="cloud-edit-published" hidden>Abrir a versão publicada para editar</button></details><details class="cloud-guests" hidden><summary>Convites por pessoa e confirmações</summary><p>Crie um link individual para cada convidado. A resposta fica salva e aparece aqui.</p><form><label>Nome do convidado<input name="guestName" maxlength="80" required></label><label>Pessoas neste convite<input name="guestCount" type="number" min="1" max="10" value="1" required></label><button type="submit">Criar convite individual</button></form><button type="button" class="cloud-import-guests">Gerar links da minha lista de convidados</button><button type="button" class="cloud-refresh-guests">Atualizar confirmações</button><div class="cloud-guest-list"></div></details>';
 panel.hidden=true;document.querySelector('.digital-delivery').after(panel);const $=selector=>panel.querySelector(selector),status=$('.cloud-status');let busy=false,chosen='';
 function current(){return billing.get(chosen)||billing.find();}
 function render(){const record=current(),delivery=record?.delivery;panel.hidden=billing.config.mode==='offline';$('.cloud-environment').textContent=billing.config.mode==='test'?'Ambiente de teste. Os presentes publicados nesta etapa são de demonstração.':'';$('.cloud-result').hidden=!delivery;$('.cloud-guests').hidden=record?.planId!=='celebrar'||!delivery||record.draftId!==getState().draftId;$('.cloud-edit-published').hidden=!delivery;$('.cloud-publish').disabled=busy||!!record&&record.draftId!==getState().draftId;$('.cloud-publish').textContent=billing.find()?.delivery?'Atualizar meu presente publicado':'Publicar e criar meu link';const rows=billing.list().filter(r=>r.mode===billing.config.mode&&r.id);$('.cloud-purchase-label').hidden=!rows.length;$('.cloud-purchase-select').replaceChildren(...rows.map(r=>new Option((billing.config.plans?.[r.planId]?.title||'Compra')+' · '+r.id.slice(-6),r.id)));$('.cloud-purchase-select').value=record?.id||'';if(!delivery)return;
  $('.cloud-link').value=delivery.url;$('.cloud-open').href=delivery.url;$('.cloud-expiry').textContent='Link disponível até '+new Date(delivery.expiresAt*1000).toLocaleDateString('pt-BR')+'. A cópia baixada continua com você.';if(window.qrcode){const q=window.qrcode(0,'M');q.addData(delivery.url);q.make();const size=q.getModuleCount(),unit=6,canvas=$('.cloud-qr');canvas.width=canvas.height=(size+8)*unit;const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.fillStyle='#000';for(let y=0;y<size;y++)for(let x=0;x<size;x++)if(q.isDark(y,x))ctx.fillRect((x+4)*unit,(y+4)*unit,unit,unit);canvas.dataset.url=delivery.url;}
 }
 billing.ready.then(render);document.addEventListener('billing:change',render);$('.cloud-purchase-select').addEventListener('change',event=>{chosen=event.target.value;render();});
 $('.cloud-publish').addEventListener('click',async()=>{if(busy)return;const data=getData();if(!data.recipient?.trim()){status.textContent='Escreva para quem é o presente antes de publicar.';return;}if(!await billing.requirePurchase(data.format,data.draftId)){status.textContent='Confirme a compra para publicar seu presente.';return;}busy=true;render();try{status.textContent='Otimizando e preparando fotos, páginas e áudio…';const file=await makeDigitalGift(data,getAudio());const delivery=await billing.publish(data,file,progress=>{status.textContent='Enviando presente compactado · '+mediaSize(progress.bytes)+(progress.bytes<progress.original?' (antes '+mediaSize(progress.original)+')':'')+'…';});chosen=billing.find(data.draftId).id;status.textContent='Seu mimo está publicado. Copie o link ou compartilhe o QR Code.';toast('Presente publicado!');render();if(data.format==='convite')await renderGuests();}catch(e){status.textContent=e.message;}finally{busy=false;render();}});
 $('.cloud-copy').addEventListener('click',async()=>{const value=$('.cloud-link');try{await navigator.clipboard.writeText(value.value);toast('Link do presente copiado.');}catch{value.focus();value.select();status.textContent='Selecione e copie o link acima.';}});
 $('.cloud-qr-save').addEventListener('click',()=>{const a=document.createElement('a');a.href=$('.cloud-qr').toDataURL('image/png');a.download='capimimo-qr-do-presente.png';a.click();});
 $('.cloud-save-access').addEventListener('click',()=>downloadFile('capimimo-acesso-da-compra.json',billing.backup()));$('.cloud-restore-access').addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;try{status.textContent='Recuperando sua compra…';const records=await billing.restore(file);chosen=records[0].id;render();$('.cloud-access').open=true;status.textContent='Acesso recuperado. Você pode abrir a versão publicada para editar.';}catch(e){status.textContent=e.message;}finally{event.target.value='';}});
 $('.cloud-edit-published').addEventListener('click',async()=>{if(busy)return;busy=true;render();try{const record=current(),payload=await billing.readPublished(record);if(await onRestore(payload,record)===false)return;status.textContent='Presente recuperado com fotos, áudio e personalização.';toast('Você já pode continuar editando.');}catch(e){status.textContent=e.message;}finally{busy=false;render();}});
 async function renderGuests(){const list=$('.cloud-guest-list');const guests=await billing.guests(current());list.replaceChildren();for(const guest of guests){const row=document.createElement('article'),name=document.createElement('strong'),text=document.createElement('p');name.textContent=guest.name;text.textContent=guest.status==='accepted'?guest.attendingCount+' presença(s) confirmada(s)':guest.status==='declined'?'Não poderá participar':'Aguardando resposta';row.append(name,text);const url=billing.guestLink(guest.id,current());if(url){const button=document.createElement('button');button.type='button';button.textContent='Copiar convite';button.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(url);toast('Convite individual copiado.');}catch{status.textContent='Link do convite: '+url;}});row.append(button);}list.append(row);}}
 const form=$('.cloud-guests form');form.addEventListener('submit',async event=>{event.preventDefault();if(busy)return;busy=true;const button=form.querySelector('button');button.disabled=true;try{await billing.addGuest(form.elements.guestName.value.trim(),Number(form.elements.guestCount.value),current());form.reset();await renderGuests();status.textContent='Convite individual criado. Copie o link para enviar à pessoa.';}catch(e){status.textContent=e.message;}finally{busy=false;button.disabled=false;}});
 $('.cloud-refresh-guests').addEventListener('click',()=>renderGuests().catch(e=>status.textContent=e.message));$('.cloud-import-guests').addEventListener('click',async()=>{if(busy)return;busy=true;try{const saved=await billing.guests(current()),names=new Set(saved.map(g=>g.name.trim().toLocaleLowerCase('pt-BR'))),guests=getState().guests||[];let count=0;for(const guest of guests){if(!guest.name?.trim()||names.has(guest.name.trim().toLocaleLowerCase('pt-BR')))continue;await billing.addGuest(guest.name,Math.min(10,Math.max(1,Number(guest.allowedCount)||1)),current());names.add(guest.name.trim().toLocaleLowerCase('pt-BR'));count++;}await renderGuests();status.textContent=count?count+' convite(s) individual(is) criado(s).':'Todos os convidados desta lista já têm um convite.';}catch(e){status.textContent=e.message;}finally{busy=false;}});
 const recoverButton=document.createElement('button');recoverButton.type='button';recoverButton.className='header-library-button header-purchase-recovery';recoverButton.textContent='Recuperar compra';recoverButton.hidden=true;document.querySelector('.announcement').append(recoverButton);const recovery=document.createElement('dialog');recovery.className='purchase-recovery-dialog';recovery.innerHTML='<button type="button" class="purchase-recovery-close">Fechar</button><h2>Voltar ao seu mimo.</h2><p>Escolha uma compra deste aparelho ou importe o arquivo de acesso que você guardou.</p><label>Arquivo de acesso<input type="file" accept="application/json,.json"></label><p class="recovery-status" role="status"></p><div class="recovery-list"></div>';document.body.append(recovery);const recoveryStatus=recovery.querySelector('.recovery-status');
 function recoverList(){const list=recovery.querySelector('.recovery-list');list.replaceChildren();const records=billing.list().filter(row=>row.mode===billing.config.mode);if(!records.length)recoveryStatus.textContent='Importe o arquivo capimimo-acesso-da-compra.json para recuperar uma compra de outro aparelho.';for(const item of records){const row=document.createElement('article'),title=document.createElement('strong'),button=document.createElement('button');title.textContent=(billing.config.plans?.[item.planId]?.title||'Compra')+' · '+item.id.slice(-6);button.type='button';button.textContent=item.status==='approved'?(item.delivery?'Abrir presente publicado':'Continuar criando'):'Ver situação da compra';row.append(title,button);button.addEventListener('click',async()=>{button.disabled=true;try{const record=billing.get(item.id);await billing.refresh(record);if(record.status==='approved'){const payload=record.delivery?await billing.readPublished(record):null;if(await onRestore(payload,record)===false)return;chosen=record.id;recovery.close();render();}else{recovery.close();document.dispatchEvent(new CustomEvent('billing:resume',{detail:record}));}}catch(e){recoveryStatus.textContent=e.message;}finally{button.disabled=false;}});list.append(row);}}
 recoverButton.addEventListener('click',()=>{recoveryStatus.textContent='';recoverList();recovery.showModal();});recovery.querySelector('.purchase-recovery-close').addEventListener('click',()=>recovery.close());recovery.querySelector('input').addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;try{recoveryStatus.textContent='Recuperando sua compra…';await billing.restore(file);recoveryStatus.textContent='Compra recuperada. Escolha o presente abaixo.';recoverList();}catch(e){recoveryStatus.textContent=e.message;}finally{event.target.value='';}});billing.ready.then(()=>recoverButton.hidden=billing.config.mode==='offline');
 return{render};
}
